select id, title, synopsis, content, source_type as sourceType, source_name as sourceName, source_link as sourceLink, user_id as userId, create_time as createTime, update_time as updateTime, deleted_flag as deletedFlag from mes_rec_reflection
deleted_flag = 0 and user_id = #{param.userId}
and id = #{param.id}
and source_type = #{param.sourceType}
and title like concat('%', #{param.title}, '%')
order by rand()
order by create_time desc
